"""Measure real prefix-KV continuation and decode after bounded prefill chunks."""
import itertools
import json
import time
from array import array

from sglang.benchmark import one_batch


def append_tokens(reqs, runner, length):
    """Continue requests using KV generated by the actual preceding forwards."""
    for req in reqs:
        prefix = len(req.full_untruncated_fill_ids)
        req.prefix_indices = runner.torch_runner.req_to_token_pool.req_to_token[req.req_pool_idx, :prefix].to(req.prefix_indices.dtype)
        req.full_untruncated_fill_ids.extend(array('q', one_batch.np.random.randint(0, 10000, length).tolist()))
        req.set_extend_range(prefix, len(req.full_untruncated_fill_ids))


def measure(runner, plan, destination, tp_rank):
    one_batch.np.random.seed(plan['random_seed'])
    with open(destination, 'a') if tp_rank == 0 else open('/dev/null', 'w') as output:
        for batch_size, prefix, length in itertools.product(plan['chunk_batch_sizes'], plan['chunk_prefix_lengths'], plan['chunk_input_lengths']):
            samples = []
            for iteration in range(6):
                runner.clear()
                reqs = one_batch.prepare_synthetic_inputs_for_latency_test(batch_size, prefix)
                runner.extend(reqs)
                append_tokens(reqs, runner, length)
                runner.synchronize()
                started = time.perf_counter()
                runner.extend(reqs)
                runner.synchronize()
                if iteration >= 3:
                    samples.append((time.perf_counter() - started) * 1000)
            if tp_rank == 0:
                output.write(json.dumps({'kind': 'prefill', 'batch_size': batch_size, 'input_len': length, 'prefix_len': prefix, 'latency_ms_samples': samples, 'warmup_iterations': 3, 'kv_seed': 'real_model_forward'}) + '\n')
                output.flush()
        for batch_size, length in itertools.product(plan['decode_batch_sizes'], plan.get('decode_input_lengths', [4000, 4200])):
            if batch_size > runner.max_batch_size(length, 32):
                continue
            samples = []
            for iteration in range(4):
                runner.clear()
                chunk = min(length, 8192 // batch_size)
                reqs = one_batch.prepare_synthetic_inputs_for_latency_test(batch_size, chunk)
                next_ids, _, batch = runner.extend(reqs)
                remaining = length - chunk
                while remaining:
                    take = min(chunk, remaining)
                    append_tokens(reqs, runner, take)
                    next_ids, _, batch = runner.extend(reqs)
                    remaining -= take
                latencies = []
                for _ in range(31):
                    runner.synchronize()
                    started = time.perf_counter()
                    next_ids, _ = runner.decode(next_ids, batch)
                    runner.synchronize()
                    latencies.append((time.perf_counter() - started) * 1000)
                if iteration:
                    samples.append(sorted(latencies)[15])
            if tp_rank == 0:
                output.write(json.dumps({'kind': 'decode', 'batch_size': batch_size, 'input_len': length, 'prefix_len': 0, 'latency_ms_samples': samples, 'warmup_iterations': 1, 'kv_seed': 'real_model_forward_chunks', 'decode_iterations_per_sample': 31}) + '\n')
                output.flush()
